import { planPath, type PathResult, type PointProblem, type TerrainDataset, type Vec2 } from '#sim';

// Planned routes for display and validation (docs/adr/0011, docs/adr/0012).
// The trainee's destination is intent; the turn points on the way are
// generated by the simulation's own path planner, so what is shown is what
// will be walked. OPFOR scenario routes use the same planning, leg by leg.

export interface PlannedLeg {
  /** The point this leg ends at (a trainee destination or a scenario route waypoint). */
  readonly waypointId: string;
  readonly to: Vec2;
  /** Generated turn points on the way (not trainee intent), or `null` when the leg is impossible. */
  readonly turns: readonly Vec2[] | null;
  /** Why the leg is impossible, for the trainee; `null` when it is fine. */
  readonly problem: string | null;
}

export interface PlannedRoute {
  readonly start: Vec2;
  readonly legs: readonly PlannedLeg[];
  /** Whether every leg can be walked. */
  readonly ok: boolean;
}

/** A trainee-facing explanation of why a point cannot be walked to. */
export function describePathProblem(
  problem: PointProblem | { readonly kind: 'unreachable' },
): string {
  switch (problem.kind) {
    case 'offTerrain':
      return 'off the map';
    case 'insideBuilding':
      return `inside building ${problem.buildingId}; soldiers cannot enter buildings`;
    case 'tooCloseToBuilding':
      return `against the wall of building ${problem.buildingId}; keep a little clear of it`;
    case 'unreachable':
      return "cannot be reached from the soldier's position";
  }
}

/** Memoizes `planPath` for one terrain; bounded so it cannot grow without limit. */
export function createPathCache(terrain: TerrainDataset, limit = 2000) {
  const cache = new Map<string, PathResult>();
  return (from: Vec2, to: Vec2): PathResult => {
    const key = `${String(from.x)},${String(from.y)}>${String(to.x)},${String(to.y)}`;
    let result = cache.get(key);
    if (!result) {
      if (cache.size >= limit) cache.clear();
      result = planPath(terrain, from, to);
      cache.set(key, result);
    }
    return result;
  };
}

/** Plans every leg of a route from `start` through `waypoints`. */
export function planRoute(
  plan: (from: Vec2, to: Vec2) => PathResult,
  start: Vec2,
  waypoints: readonly { readonly id: string; readonly x: number; readonly y: number }[],
): PlannedRoute {
  let from = start;
  const legs = waypoints.map((w) => {
    const to = { x: w.x, y: w.y };
    const path = plan(from, to);
    from = to;
    return path.ok
      ? { waypointId: w.id, to, turns: path.turns, problem: null }
      : { waypointId: w.id, to, turns: null, problem: describePathProblem(path.problem) };
  });
  return { start, legs, ok: legs.every((l) => l.turns !== null) };
}
